import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  counters: defineTable({
    runId: v.string(),
    count: v.number(),
  }).index("by_runId", ["runId"]),
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";

// Fetch the counter for the given runId.
export const getCounter = query({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    const counter = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .first();
    return counter ?? null;
  },
});

// Increment the counter for the given runId, creating it if it doesn't exist.
export const increment = mutation({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    const existing = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .first();
    if (existing) {
      await ctx.db.patch(existing._id, { count: existing.count + 1 });
      return existing.count + 1;
    }
    const newId = await ctx.db.insert("counters", { runId, count: 1 });
    return 1;
  },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { ConvexProvider, ConvexReactClient } from "convex/react";
import App from "./App.jsx";
import "./index.css";

const convexUrl = import.meta.env.VITE_CONVEX_URL;
const convex = new ConvexReactClient(convexUrl);

createRoot(document.getElementById("root")).render(
  <StrictMode>
    <ConvexProvider client={convex}>
      <App />
    </ConvexProvider>
  </StrictMode>
);

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { ConvexProvider, ConvexReactClient } from "convex/react";
import App from "./App.jsx";
import "./index.css";

const convexUrl = import.meta.env.VITE_CONVEX_URL;
const convex = new ConvexReactClient(convexUrl);

createRoot(document.getElementById("root")).render(
  <StrictMode>
    <ConvexProvider client={convex}>
      <App />
    </ConvexProvider>
  </StrictMode>
);

import { useQuery, useMutation } from "convex/react";
import { api } from "../convex/_generated/api";
import "./App.css";

function App() {
  const runId = import.meta.env.VITE_RUN_ID;
  const counter = useQuery(api.counter.getCounter, { runId });
  const increment = useMutation(api.counter.increment);

  const count = counter?.count ?? 0;

  const handleIncrement = () => {
    increment({ runId });
  };

  return (
    <section id="center">
      <h1>Collaborative Counter</h1>
      <p>Shared across all clients in real time.</p>
      <div className="count-display">{count}</div>
      <button type="button" className="counter" onClick={handleIncrement}>
        Increment
      </button>
    </section>
  );
}

export default App;

